import React, { useState } from "react";
import "./SpendingPriority.css";

function SpendingPriority({ data = {}, updateData, onNext }) {
  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [selected, setSelected] = useState({});
  const [values, setValues] = useState({});

  const toggleCategory = (cat) => {
    setSelected(prev => ({
      ...prev,
      [cat]: !prev[cat]
    }));
  };

  const handleSlider = (cat, value) => {
    setValues(prev => ({
      ...prev,
      [cat]: Number(value)
    }));
  };

  const handleContinue = () => {
    updateData({ spendingPriorities: values });
    onNext();
  };

  return (
    <div className="spending-container">
      <div className="spending-card">
        <h2 className="spending-title">Set Spending Priorities</h2>

        <div className="spending-grid">
          {categories.map(cat => (
            <div key={cat} className="spending-item">
              <div
                className="spending-category"
                onClick={() => toggleCategory(cat)}
              >
                {cat}
              </div>

              {selected[cat] && (
                <input
                  type="range"
                  min="0"
                  max="5"
                  value={values[cat] || 0}
                  onChange={(e) => handleSlider(cat, e.target.value)}
                />
              )}
            </div>
          ))}
        </div>

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default SpendingPriority;
